local ADDON_NAME, ns = ...

-- Quest objective items for Classic Era. Two kinds, told apart by the Q
-- source tag:
--   without Q - obtainable WITHOUT the quest in the log (regular drops,
--     gathered/fished/crafted items, limited-stock vendor goods): the
--     save-or-sell tooltip lines.
--   with Q - quest-bound/conditional (only obtainable with the quest, or
--     not tradeable): the "can be deleted once the quest is done" check.
-- Items vendors sell in unlimited quantity are excluded entirely (no
-- keep-or-sell decision exists for them).
--
-- Quest/item names are comments only - display names come from the quest
-- log APIs / GetItemInfo at runtime, so they are always localized.
--
-- add(questId, items[, flags[, extra]])
--   items: { [itemId] = requiredCount, ... } (may be empty for quests that
--     only appear as a qstart() target)
--   flags: "A" Alliance-only, "H" Horde-only, "R" repeatable (combinable)
--   extra: { classes = <class mask>, races = <race mask>,
--            skill = <required skill line id>, lvl = <quest level>,
--            zone = <AreaTable id> }
-- src(itemId, tags)
--   Obtain sources: D drop, G gathered, F fished, C crafted, V vendor
--   (limited stock), Q quest-bound/conditional. Items without a D tag can
--   be hidden via the "Include gathered/fished/crafted items" option.
-- qstart(itemId, questId)
--   The item starts this quest when used; once the quest is completed the
--   leftover item gets a "can be deleted" line.
local add, src, qstart, qprov = ns.NewQuestDB()

